-- Guards: the two new partial UNIQUE indexes must not be creatable over dirty
-- data silently. Fail the whole migration loudly instead.
DO $$
BEGIN
  IF (SELECT count(*) FROM "agent_behavior" WHERE "is_active") > 1 THEN
    RAISE EXCEPTION 'migration 0020: % active agent_behavior rows found — exactly one may be active; deactivate extras and re-run',
      (SELECT count(*) FROM "agent_behavior" WHERE "is_active");
  END IF;
  IF EXISTS (
    SELECT 1 FROM "orders"
    WHERE "status" = 'draft' AND "conversation_id" IS NOT NULL
    GROUP BY "conversation_id" HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'migration 0020: multiple draft orders share one conversation — resolve duplicates and re-run';
  END IF;
END $$;--> statement-breakpoint
